---@see 合成次数
function EquipTaskGoal.FlushSynthesisCount(actor, type, goal_id, goal_count, param)
    if table.isNullOrEmpty(param) then
        return goal_count
    end
    local synthesisId = param["synthesisid"]
    local num = param["num"]
    local needCount = ConfigDataManager.getTableValue("cfg_task_target", "goalcount", "id", goal_id)
    if needCount == nil or goal_count >= tonumber(needCount) then
        return goal_count
    end
    local goalParam = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam", "id", goal_id)
    if goalParam == nil or tonumber(goalParam) ~= tonumber(synthesisId) then
        return goal_count
    end
    --local synthesisCount = tonumber(getplaydef(actor,"T$_ItemSynthesisCount"))
    return goal_count + num
end

