---@see 首饰升级
function EquipTaskGoal.FlushJewelryLvUp(actor, _, goal_id, _, param)
    local target_type_str = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam", "id", goal_id)
    local target_lv_str = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam2", "id", goal_id)

    local target_type = string.isNullOrEmpty(target_type_str) and 0 or tonumber(target_type_str)
    local target_lv = string.isNullOrEmpty(target_lv_str) and 0 or tonumber(target_lv_str)

    local max_count = 0

    local function checkEquip(equip, cfg_id)
        if table.isEmpty(equip) then
            return 0
        end
        local level = equip.ssuplv or 0
        local subtype_str = ConfigDataManager.getTableValue("cfg_item", "subtype", "id", cfg_id)
        local subtype = string.isNullOrEmpty(subtype_str) and 0 or tonumber(subtype_str)
        if target_type == tonumber(subtype) and level >= target_lv then
            return 1
        end
        return 0
    end

    if not table.isEmpty(param) then
        local id = param[1]
        local cfg_id = param[2]
        local equip = EquipAndAppear.getItemExtData(actor, id)
        max_count = max_count + checkEquip(equip, cfg_id)
    else
        local all_equip = getputonequipinfo(actor)
        if table.isEmpty(all_equip) then
            return 0
        end
        for _, v in pairs(all_equip) do
            local equip = EquipAndAppear.getItemExtData(actor, v.id)
            max_count = max_count + checkEquip(equip, v.cfgid)
        end
    end
    return max_count
end

