---@see 重新获取一个指定道具
function EquipTaskGoal.FlushReGetItem(_, _, goal_id, goal_count, param)
    if table.isEmpty(param) then
        return goal_count
    end
    local cfg_id = param[1]
    local count = param[2]
    local target_str = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam2", "id", goal_id)
    local target_arr = string.split(target_str, "#")
    if table.isEmpty(target_arr) then
        return goal_count
    end

    local needArr = {}
    for i = 1, #target_arr do
        local itemCfgId = target_arr[i]
        table.insert(needArr, itemCfgId)
        local bindId = ConfigDataManager.getTableValue("cfg_item", "bindequalitem", "id", itemCfgId)
        if not string.isNullOrEmpty(bindId) then
           table.insert(needArr, bindId)
        end
    end
    if not table.contains(needArr, tostring(cfg_id)) then
        return goal_count
    end
    return goal_count + count
end

