---@see 卓越词条
function EquipTaskGoal.FlushExcellenceAttr(actor, _, goal_id, goal_count, _)
    local all_equip = getputonequipinfo(actor)
    if table.isEmpty(all_equip) then
        return 0
    end

    local max_count = 0
    local target_part = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam", "id", goal_id)
    for _, equip in pairs(all_equip) do
        local entries_size = #equip.entries
        if tonumber(target_part) > 0 then
            local part = gameequip.pos(equip.equipindex)
            if tonumber(part) == target_part then
                return entries_size
            end
        end
        -- 任意部位大于指定数量
        if entries_size >= tonumber(goal_count) then
            return entries_size
        end
        -- 记录最大值
        if entries_size > max_count then
            max_count = entries_size
        end
    end
    return max_count
end

---@see 穿戴装备卓越词条数量
function EquipTaskGoal.FlushExcellenceAttrCount(actor, _, goal_id, goal_count, _)
    local target_type_str = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam", "id", goal_id)
    local target_type = string.isNullOrEmpty(target_type_str) and 0 or tonumber(target_type_str)
    if target_type < 1 then
        -- 已穿戴的卓越词条数量
        return EquipAndAppear.GetEquipsSumExcellentEntryCount(actor)
    end

    local sum_value = 0
    local all_equip = getputonequipinfo(actor)
    if table.isEmpty(all_equip) then
        return sum_value
    end

    for _, equip in pairs(all_equip) do
        local sub_type = ConfigDataManager.getTableValue("cfg_item", "subtype", "id", equip.cfgid)
        if tonumber(sub_type) == target_type then
            sum_value = sum_value + #equip.entries
        end
    end
    return sum_value
end

