        return goal_count
    end

    local target = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam", "id", goal_id)
    local recovery_id = string.tonumber(target)
    if recovery_id < 1 then
        return goal_count
    end
    local count = param[recovery_id] == nil and 0 or param[recovery_id]
    return goal_count + count
end

