---@see 穿戴指定装备
function EquipTaskGoal.SpecificStageEquip(actor, _, goal_id, goal_count, param)
    local needStage = tonumber(ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam", "id", goal_id))
    local ratingParam = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam2", "id", goal_id)
    local ratingLimit = {}
    if not string.isNullOrEmpty(ratingParam) then
        local ratingArray = string.split(ratingParam, "#")
        for i = 1, #ratingArray do
            table.insert(ratingLimit, tonumber(ratingArray[i]))
        end
    end
    --jprint("穿戴指定品阶装备任务", needStage, ratingLimit)
    local sumCount = EquipAndAppear.CheckSpecificStageEquipCount(actor, needStage, ratingLimit)
    local finalCount = math.max(goal_count, sumCount)
    return finalCount
end

---@see 镶嵌卡牌
function EquipTaskGoal.InlaidTransformationCard(_, _, goal_id, goal_count, param)
    if table.isEmpty(param) then
        return goal_count
    end

    local card_id = tonumber(param[1])
    local card_quality = tonumber(param[2])

    local target = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam", "id", goal_id)
    local target_2 = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam2", "id", goal_id)
    local target_id = string.tonumber(target)
    local target_ids = string.split(target_2, "#")

    local function matchesTarget()
        if target_id > 0 and #target_ids > 0 then
            return target_id == card_quality and table.contains(target_ids, card_id)
        elseif target_id > 0 then
            return target_id == card_quality
        elseif #target_ids > 0 then
            return table.contains(target_ids, card_id)
        end
        return true
    end

    if matchesTarget() then
        return goal_count + 1
    end
    return goal_count
end

---@see 合成卡牌
function EquipTaskGoal.FlushSynthesisCard(_, _, goal_id, goal_count, param)
    local item_type = string.tonumber(param)
    if item_type < 1 then
        return goal_count
    end

    local target_str = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam", "id", goal_id)
    local target_id = string.tonumber(target_str)
    if target_id > 0 and item_type ~= target_id then
        return goal_count
    end
    return goal_count + 1
end



---@see 强化装备
function EquipTaskGoal.strengthenEquip(actor, _, goal_id, goal_count, param)
    if param==nil then
        -- 接取任务的时候内置默认会刷新，但是参数内置是null
         return goal_count
    end
    local success = param.success
    local partStr = param.part
    local target = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam", "id", goal_id)
    local target_2 = ConfigDataManager.getTableValue("cfg_task_target", "taskgoalparam2", "id", goal_id)
    if string.tonumber(target) == 1 and success ~= true then
        return goal_count
    end

    local partList = string.splitInt(target_2, "#")
    if table.count(partList) > 0 then
        local met = false
        local thisParts = string.splitInt(partStr, "#")
        for key, part in pairs(thisParts) do
            if table.contains(partList, part) then
                met = true
                break
            end
        end
        if met == false then
            return goal_count
        end
    end

    return goal_count + 1
end
